import fs from 'node:fs';
import assert from 'node:assert/strict';
const [one,two]=process.argv.slice(2);
const a=JSON.parse(fs.readFileSync(one)); const b=JSON.parse(fs.readFileSync(two));
assert.deepEqual(a.cases,b.cases,'two captures differ');
assert.equal(a.cases.length,14);
const find=input=>a.cases.find(row=>row.input===input);
for(const input of ['hello','/unknown','/new','/plan test','/projects\tfoo'])assert.equal(find(input).handled,false,input);
assert.equal(find('  /项目列表 unused  ').replies[0],'📂 项目列表：\n\n• Alpha ✅\n• alpha\n\n发送 /switch-project <项目名> 切换 WorkSpace');
assert.deepEqual(find('/切换项目 alpha').calls,['projects','bind:two','reset']);
assert.equal(find('/切换项目 alpha').replies[0],'已切换到项目：alpha\n路径：/two\n（已自动创建新会话）');
assert.equal(find('/switch-project ALP').project,'one');
assert.match(find('/switch-project missing').replies[0],/未找到匹配/);
assert.match(find('/search').replies[0],/^用法/);
const search=find('/search dog --all --limit 2').calls[0].search;
assert.deepEqual({query:search.query,limit:search.limit,projectRoot:search.projectRoot},{query:'dog',limit:2,projectRoot:undefined});
assert.match(find('/帮助').replies[0],/\/search \(\/find, \/grep, \/搜索\)/);
assert.match(find('/update invalid').replies[0],/^用法/);
console.log('14 cases verified');
